    limitations: ["Very few machines and one approved indication", "Dose depends on boron uptake, which varies by patient", "Evidence limited to small studies"],
    cancers: ["head-and-neck", "glioblastoma", "melanoma", "sarcoma"], technologies: ["bnct", "proton-therapy-systems", "carbon-ion-synchrotrons"], related: ["radiosurgery-srs", "imrt-igrt", "targeted-alpha-therapy"],
    companies: ["sumitomo-heavy-industries", "stella-pharma", "neutron-therapeutics", "neuboron-medtech", "tae-life-sciences"],
